//! Service-side sealing (M5a-04; D-045 M5-D7; M5-INTERFACES J-6, J-2, J-3).
//!
//! The host (hook client, MCP shim, CLI client; agent side, no key) proposes an action; the
//! service builds the sealed `ActionRequest` itself:
//!
//! - **From configuration only:** `principal.id` and `principal.roles` from the per-uid
//!   binding of the admitting socket; `principal.verified_by` = the binding's adapter id;
//!   `principal.authn_method` = `os_peer_credential`; `tenant_id` and `project_id` from the
//!   (socket, uid) binding.
//! - **Generated by the service:** `session_id`, one per admitted connection (random, from
//!   the OS random source; never from the host).
//! - **Always null:** `agent_id` and `parent_session_id`. Host-provided identity values are
//!   accepted only under `host_asserted` (`agent_id`, `host_session_id`, `parent_agent_id`,
//!   `parent_session_id`, `tool_name`, `host_version`), are returned with the label
//!   `host-asserted` and a digest, and are **never authority**. A proposal that sets any
//!   identity member itself is refused `IDENTITY_UNVERIFIED`.
//! - **Idempotency scoped by OS principal (J-2):** the request's `idempotency_key` is
//!   derived from (`os_principal`, tenant, project, client key), so two uids can neither
//!   collide nor probe each other's keys.
//! - **Without a trusted agent identity (until M5b-06):** grant consumption is agent-specific
//!   (D-042 X2: grants bound to the exact approved agent), so a proposal that names a grant
//!   is refused `IDENTITY_UNVERIFIED`; it is never weakened to a principal-level check.
//!   `delegation_chain` stays `unavailable`.
//!
//! The request is validated by the kernel contract parser, sealed `seal/2` with the
//! binding's ingress key (active in the key source at trusted time) and verified through
//! [`verify_ingress_keyed`], so the result is exactly what the broker accepts.
//!
//! **Recorded limitation:** the `ActionRequest` contract is closed (`writ-kernel`
//! `ActionRequest::from_value`), so `host_asserted` cannot be inside the MACed request
//! bytes without a versioned contract change (M5b-01). Until then it travels beside the
//! sealed request with its D-006 digest; it is never authority either way.

use std::fs::File;
use std::io::{self, Read};

use writ_broker::ingress::{verify_ingress_keyed, IngressBindings, Seal, VerifiedRequest};
use writ_broker::keys::{issuing_named_key_at_use, KeyPurpose, KeyRevocations, KeySource};
use writ_broker::writ_kernel::contracts::ActionRequest;
use writ_broker::writ_kernel::json::{self, Digest, Map, Value};
use writ_broker::writ_kernel::time::Timestamp;

use crate::config::HostBinding;

/// `principal.authn_method` of every service-sealed request.
pub const AUTHN_METHOD: &str = "os_peer_credential";
/// The `ActionRequest` contract version sealed here.
pub const REQUEST_CONTRACT_VERSION: &str = "2.0";
/// Members a `host_asserted` object may carry (each a string or null).
pub const HOST_ASSERTED_MEMBERS: [&str; 6] = [
    "agent_id",
    "host_session_id",
    "parent_agent_id",
    "parent_session_id",
    "tool_name",
    "host_version",
];
/// Longest `host_asserted` value in bytes.
pub const MAX_HOST_ASSERTED_BYTES: usize = 256;

/// Members a proposal may carry.
const PROPOSAL_MEMBERS: [&str; 8] = [
    "request_id",
    "trace_id",
    "idempotency_key",
    "action",
    "deadline_at",
    "expected_state_revision",
    "host_asserted",
    "grant",
];
/// Identity members only the service sets; a proposal carrying one is refused.
const IDENTITY_MEMBERS: [&str; 7] = [
    "principal",
    "tenant_id",
    "project_id",
    "session_id",
    "agent_id",
    "parent_session_id",
    "delegation_chain",
];

/// Why a proposal was not sealed.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SealRefusal {
    /// An identity member set by the host, or a grant whose consumption needs a trusted
    /// agent identity (J-6).
    IdentityUnverified,
    /// Not a proposal object with valid members, or the built request fails the contract.
    SchemaInvalid,
    /// The binding's ingress key is not active in the key source at trusted time, or the
    /// key source is unavailable.
    KeysUnavailable,
    /// The sealed request did not verify (fail closed; not expected).
    IngressUnauthenticated,
}

impl SealRefusal {
    /// The internal code (audit).
    pub fn code(self) -> &'static str {
        match self {
            SealRefusal::IdentityUnverified => "IDENTITY_UNVERIFIED",
            SealRefusal::SchemaInvalid => "REQUEST_SCHEMA_INVALID",
            SealRefusal::KeysUnavailable => "KEYS_UNAVAILABLE",
            SealRefusal::IngressUnauthenticated => "INGRESS_UNAUTHENTICATED",
        }
    }

    /// The external code (INV-44: generic unless the code describes only the caller's own
    /// input).
    pub fn external_code(self) -> &'static str {
        writ_broker::writ_kernel::refusal::external_code(self.code())
    }
}

/// The admitted connection a proposal arrives on.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ConnectionIdentity {
    /// `uid:<n>` from `SO_PEERCRED` (M5-D7: the OS principal only).
    pub os_principal: String,
    /// The connection's random session id (`sess-` and 32 hex digits).
    pub session_id: String,
    /// The (socket, uid) binding.
    pub binding: HostBinding,
}

impl ConnectionIdentity {
    /// The identity of a connection admitted for `uid` with `binding`, with a fresh session
    /// id from the OS random source.
    pub fn new(uid: u32, binding: HostBinding) -> io::Result<ConnectionIdentity> {
        let mut bytes = [0u8; 16];
        File::open("/dev/urandom")?.read_exact(&mut bytes)?;
        let hex: String = bytes.iter().map(|b| format!("{b:02x}")).collect();
        Ok(ConnectionIdentity {
            os_principal: writ_rpc::os_principal(uid),
            session_id: format!("sess-{hex}"),
            binding,
        })
    }
}

/// A sealed, verified request with the host-asserted values beside it.
#[derive(Clone, Debug)]
pub struct Sealed {
    /// The request as the broker receives it.
    pub verified: VerifiedRequest,
    /// The `seal/2` wire form.
    pub seal: Value,
    /// `host_asserted` as received (label `host-asserted`; never authority).
    pub host_asserted: Option<Value>,
    /// D-006 digest of the canonical `host_asserted` object.
    pub host_asserted_digest: Option<String>,
}

/// The idempotency key the service uses for a client key (J-2).
pub fn scoped_idempotency_key(
    os_principal: &str,
    tenant_id: &str,
    project_id: &str,
    client_key: &str,
) -> Option<String> {
    let doc = json::obj([
        ("contract", json::s("writ-idempotency-scope/1")),
        ("os_principal", json::s(os_principal)),
        ("tenant_id", json::s(tenant_id)),
        ("project_id", json::s(project_id)),
        ("client_key", json::s(client_key)),
    ]);
    json::canonical(&doc)
        .ok()
        .map(|t| Digest::of_bytes(t.as_bytes()).to_string())
}

fn bounded_text(v: Option<&Value>, max: usize) -> Result<Option<String>, SealRefusal> {
    match v {
        None => Ok(None),
        Some(Value::Str(t)) if !t.is_empty() && t.len() <= max => Ok(Some(t.clone())),
        Some(_) => Err(SealRefusal::SchemaInvalid),
    }
}

fn host_asserted(v: Option<&Value>) -> Result<Option<Value>, SealRefusal> {
    let Some(v) = v else { return Ok(None) };
    let m = v.as_obj().ok_or(SealRefusal::SchemaInvalid)?;
    for (k, val) in m {
        if !HOST_ASSERTED_MEMBERS.contains(&k.as_str()) {
            return Err(SealRefusal::SchemaInvalid);
        }
        match val {
            Value::Null => {}
            Value::Str(t) if t.len() <= MAX_HOST_ASSERTED_BYTES => {}
            _ => return Err(SealRefusal::SchemaInvalid),
        }
    }
    Ok(Some(v.clone()))
}

/// Build the `ActionRequest` for `proposal` on `conn` (module documentation).
pub fn build_request(
    conn: &ConnectionIdentity,
    proposal: &Value,
) -> Result<(Value, Option<Value>), SealRefusal> {
    let m = proposal.as_obj().ok_or(SealRefusal::SchemaInvalid)?;
    if m.keys().any(|k| IDENTITY_MEMBERS.contains(&k.as_str())) {
        return Err(SealRefusal::IdentityUnverified);
    }
    if m.keys().any(|k| !PROPOSAL_MEMBERS.contains(&k.as_str())) {
        return Err(SealRefusal::SchemaInvalid);
    }
    if m.contains_key("grant") {
        return Err(SealRefusal::IdentityUnverified);
    }
    let asserted = host_asserted(m.get("host_asserted"))?;
    let client_key =
        bounded_text(m.get("idempotency_key"), 200)?.ok_or(SealRefusal::SchemaInvalid)?;
    let b = &conn.binding;
    let key = scoped_idempotency_key(&conn.os_principal, &b.tenant_id, &b.project_id, &client_key)
        .ok_or(SealRefusal::SchemaInvalid)?;
    let mut principal = Map::new();
    principal.insert("id".into(), json::s(&b.principal_id));
    principal.insert("verified_by".into(), json::s(&b.adapter_id));
    principal.insert("authn_method".into(), json::s(AUTHN_METHOD));
    principal.insert(
        "roles".into(),
        Value::Arr(b.roles.iter().map(|r| json::s(r)).collect()),
    );
    let mut r = Map::new();
    r.insert("contract_version".into(), json::s(REQUEST_CONTRACT_VERSION));
    for k in ["request_id", "trace_id"] {
        r.insert(
            k.into(),
            m.get(k).cloned().ok_or(SealRefusal::SchemaInvalid)?,
        );
    }
    r.insert("tenant_id".into(), json::s(&b.tenant_id));
    r.insert("principal".into(), Value::Obj(principal));
    r.insert("project_id".into(), json::s(&b.project_id));
    r.insert("session_id".into(), json::s(&conn.session_id));
    r.insert("agent_id".into(), Value::Null);
    r.insert("parent_session_id".into(), Value::Null);
    r.insert("idempotency_key".into(), json::s(&key));
    r.insert(
        "expected_state_revision".into(),
        m.get("expected_state_revision")
            .cloned()
            .unwrap_or(Value::Null),
    );
    r.insert("policy_bundle_sha".into(), Value::Null);
    r.insert(
        "deadline_at".into(),
        m.get("deadline_at").cloned().unwrap_or(Value::Null),
    );
    r.insert(
        "action".into(),
        m.get("action").cloned().ok_or(SealRefusal::SchemaInvalid)?,
    );
    let request = Value::Obj(r);
    ActionRequest::from_value(&request).map_err(|_| SealRefusal::SchemaInvalid)?;
    Ok((request, asserted))
}

/// The lifetime a seal is issued for (J-3 issuing rule): the sealed request is consumed by
/// this service at once (T-reserve and T-dispatch), so like a permit it must not outlive
/// its key within this bound plus the margin.
pub const SEAL_LIFETIME_SECONDS: u64 = 30;

/// Build, seal (`seal/2`) and verify the request for `proposal` on `conn` with the
/// binding's ingress key from `keys` at trusted time `now`. M5a-13 L9: the key is chosen by
/// the J-3 issuing rule for the binding's key id ([`KeySource::issuing_named_key`]: valid,
/// not revoked, `not_after` at least `now` + [`SEAL_LIFETIME_SECONDS`] + margin) and is
/// checked against the ledger's revocations (`revocations`).
pub fn seal(
    conn: &ConnectionIdentity,
    proposal: &Value,
    keys: &dyn KeySource,
    revocations: &dyn KeyRevocations,
    now: Timestamp,
) -> Result<Sealed, SealRefusal> {
    let (request, asserted) = build_request(conn, proposal)?;
    let b = &conn.binding;
    let material = issuing_named_key_at_use(
        keys,
        revocations,
        KeyPurpose::Ingress,
        &b.ingress_key_id,
        now,
        std::time::Duration::from_secs(SEAL_LIFETIME_SECONDS),
    )
    .map_err(|_| SealRefusal::KeysUnavailable)?;
    let key = material.ingress().ok_or(SealRefusal::KeysUnavailable)?;
    let seal = Seal::create_keyed(&request, &b.adapter_id, &b.ingress_key_id, key)
        .ok_or(SealRefusal::SchemaInvalid)?
        .to_value();
    let mut bindings = IngressBindings::new();
    if !bindings.bind(&b.adapter_id, b.ingress_key_id.clone()) {
        return Err(SealRefusal::KeysUnavailable);
    }
    let verified = verify_ingress_keyed(&request, Some(&seal), keys, &bindings, now)
        .map_err(|_| SealRefusal::IngressUnauthenticated)?;
    let host_asserted_digest = match &asserted {
        Some(a) => Some(
            json::canonical(a)
                .map(|t| Digest::of_bytes(t.as_bytes()).to_string())
                .map_err(|_| SealRefusal::SchemaInvalid)?,
        ),
        None => None,
    };
    Ok(Sealed {
        verified,
        seal,
        host_asserted: asserted,
        host_asserted_digest,
    })
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
mod tests {
    use super::*;
    use writ_broker::keys::{KeyId, KeyValidity, Material, MemoryKeyRegistry, MemoryKeySource};

    fn ts(s: &str) -> Timestamp {
        Timestamp::parse_rfc3339(s).unwrap()
    }

    fn binding(uid: u32, tenant: &str) -> HostBinding {
        HostBinding {
            uid,
            tenant_id: tenant.into(),
            project_id: "web".into(),
            principal_id: "agent:writ-agent".into(),
            roles: vec!["agent".into()],
            adapter_id: "writ-host-adapter:cli".into(),
            ingress_key_id: KeyId::parse("ingress/k1").unwrap(),
        }
    }

    fn conn(uid: u32) -> ConnectionIdentity {
        ConnectionIdentity::new(uid, binding(uid, "acme")).unwrap()
    }

    fn keys() -> MemoryKeySource {
        let mut s = MemoryKeySource::new(60);
        s.insert(
            KeyId::parse("ingress/k1").unwrap(),
            Material::new(KeyPurpose::Ingress, vec![0x11; 32]).unwrap(),
            KeyValidity::new(ts("2026-01-01T00:00:00Z"), ts("2027-01-01T00:00:00Z")).unwrap(),
        );
        s
    }

    fn proposal(extra: &[(&str, Value)]) -> Value {
        let mut m = json::parse(
            br#"{"request_id":"r1","trace_id":"t1","idempotency_key":"k1",
            "action":{"kind":"file.write","resource":{"uri":"file:///work/a","canonical_resource_id":"workspace:acme/web/a"},
            "action_digest":"sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}}"#,
        )
        .unwrap();
        if let Value::Obj(o) = &mut m {
            for (k, v) in extra {
                o.insert((*k).to_string(), v.clone());
            }
        }
        m
    }

    fn now() -> Timestamp {
        ts("2026-11-16T12:00:00Z")
    }

    /// M5a-13 L9: sealing applies the J-3 issuing rule to the binding's key (valid, not
    /// revoked in the ledger, `not_after` at least now + lifetime + margin).
    #[test]
    fn sealing_applies_the_issuing_rule_and_the_ledger_revocations() {
        use writ_broker::keys::{KeyRegistry, KeyRevocation, MaterialDigest, OsActor};
        let c = conn(1001);
        // The key ends 2027-01-01T00:00:00Z: 30 s + 60 s margin before it still seals.
        assert!(seal(
            &c,
            &proposal(&[]),
            &keys(),
            &MemoryKeyRegistry::new(),
            ts("2026-12-31T23:58:30Z")
        )
        .is_ok());
        assert_eq!(
            seal(
                &c,
                &proposal(&[]),
                &keys(),
                &MemoryKeyRegistry::new(),
                ts("2026-12-31T23:58:31Z")
            )
            .err(),
            Some(SealRefusal::KeysUnavailable)
        );
        let mut ledger = MemoryKeyRegistry::new();
        ledger
            .revoke(KeyRevocation {
                key_id: KeyId::parse("ingress/k1").unwrap(),
                material: MaterialDigest::of(&[0x11; 32]),
                purpose: KeyPurpose::Ingress,
                revoked_at: now(),
                actor: OsActor { uid: 0, pid: 1 }.document().unwrap(),
                reason: "r".into(),
            })
            .unwrap();
        assert_eq!(
            seal(&c, &proposal(&[]), &keys(), &ledger, now()).err(),
            Some(SealRefusal::KeysUnavailable)
        );
    }

    #[test]
    fn identity_comes_from_configuration_and_the_connection_only() {
        let c = conn(1001);
        let s = seal(
            &c,
            &proposal(&[]),
            &keys(),
            &MemoryKeyRegistry::new(),
            now(),
        )
        .unwrap();
        let r = s.verified.request().as_obj().unwrap();
        let p = r["principal"].as_obj().unwrap();
        assert_eq!(p["id"], json::s("agent:writ-agent"));
        assert_eq!(p["verified_by"], json::s("writ-host-adapter:cli"));
        assert_eq!(p["authn_method"], json::s(AUTHN_METHOD));
        assert_eq!(r["tenant_id"], json::s("acme"));
        assert_eq!(r["project_id"], json::s("web"));
        assert_eq!(r["session_id"], json::s(&c.session_id));
        assert_eq!(r["agent_id"], Value::Null);
        assert_eq!(r["parent_session_id"], Value::Null);
        assert_eq!(s.verified.adapter_id(), "writ-host-adapter:cli");
        let (id, _) = s.verified.seal_key().unwrap();
        assert_eq!(id.as_str(), "ingress/k1");
        assert_eq!(s.seal.as_obj().unwrap().len(), 3, "seal/2 wire form");
    }

    #[test]
    fn session_ids_are_per_connection_and_random() {
        let a = conn(1001);
        let b = conn(1001);
        assert_ne!(a.session_id, b.session_id);
        assert!(a.session_id.starts_with("sess-") && a.session_id.len() == 37);
    }

    #[test]
    fn host_set_identity_members_are_refused_identity_unverified() {
        for member in IDENTITY_MEMBERS {
            let p = proposal(&[(member, json::s("forged"))]);
            assert_eq!(
                seal(&conn(1001), &p, &keys(), &MemoryKeyRegistry::new(), now()).err(),
                Some(SealRefusal::IdentityUnverified),
                "{member}"
            );
        }
        let p = proposal(&[("grant", json::s("approval/g1"))]);
        assert_eq!(
            seal(&conn(1001), &p, &keys(), &MemoryKeyRegistry::new(), now()).err(),
            Some(SealRefusal::IdentityUnverified)
        );
        assert_eq!(
            SealRefusal::IdentityUnverified.code(),
            "IDENTITY_UNVERIFIED"
        );
        assert_eq!(
            SealRefusal::IdentityUnverified.external_code(),
            "PROMOTION_REFUSED"
        );
    }

    #[test]
    fn host_asserted_values_are_labelled_beside_the_request_never_inside_it() {
        let asserted = json::obj([
            ("agent_id", json::s("subagent-7")),
            ("parent_session_id", json::s("host-session-1")),
            ("tool_name", json::s("Write")),
        ]);
        let p = proposal(&[("host_asserted", asserted.clone())]);
        let s = seal(&conn(1001), &p, &keys(), &MemoryKeyRegistry::new(), now()).unwrap();
        let r = s.verified.request().as_obj().unwrap();
        assert_eq!(r["agent_id"], Value::Null);
        assert_eq!(r["parent_session_id"], Value::Null);
        assert_eq!(s.host_asserted, Some(asserted));
        assert!(s.host_asserted_digest.unwrap().starts_with("sha256:"));
        for bad in [
            json::obj([("principal", json::s("x"))]),
            json::obj([("agent_id", Value::Int(1))]),
            json::obj([(
                "agent_id",
                json::s(&"x".repeat(MAX_HOST_ASSERTED_BYTES + 1)),
            )]),
            json::s("not an object"),
        ] {
            let p = proposal(&[("host_asserted", bad)]);
            assert_eq!(
                seal(&conn(1001), &p, &keys(), &MemoryKeyRegistry::new(), now()).err(),
                Some(SealRefusal::SchemaInvalid)
            );
        }
    }

    #[test]
    fn idempotency_keys_are_scoped_by_os_principal_and_binding() {
        let k = |p: &str, t: &str| scoped_idempotency_key(p, t, "web", "k1").unwrap();
        assert_ne!(k("uid:1001", "acme"), k("uid:1002", "acme"));
        assert_ne!(k("uid:1001", "acme"), k("uid:1001", "other"));
        let a = seal(
            &conn(1001),
            &proposal(&[]),
            &keys(),
            &MemoryKeyRegistry::new(),
            now(),
        )
        .unwrap();
        let b = seal(
            &conn(1002),
            &proposal(&[]),
            &keys(),
            &MemoryKeyRegistry::new(),
            now(),
        )
        .unwrap();
        let key = |s: &Sealed| s.verified.request().as_obj().unwrap()["idempotency_key"].clone();
        assert_ne!(key(&a), key(&b));
        assert_ne!(key(&a), json::s("k1"));
    }

    #[test]
    fn unknown_members_bad_requests_and_inactive_keys_are_refused() {
        let p = proposal(&[("policy_bundle_sha", json::s("x"))]);
        assert_eq!(
            seal(&conn(1001), &p, &keys(), &MemoryKeyRegistry::new(), now()).err(),
            Some(SealRefusal::SchemaInvalid)
        );
        let p = proposal(&[("action", json::s("not an action"))]);
        assert_eq!(
            seal(&conn(1001), &p, &keys(), &MemoryKeyRegistry::new(), now()).err(),
            Some(SealRefusal::SchemaInvalid)
        );
        assert_eq!(
            seal(
                &conn(1001),
                &json::s("x"),
                &keys(),
                &MemoryKeyRegistry::new(),
                now()
            )
            .err(),
            Some(SealRefusal::SchemaInvalid)
        );
        // The key is outside its validity window: no seal.
        assert_eq!(
            seal(
                &conn(1001),
                &proposal(&[]),
                &keys(),
                &MemoryKeyRegistry::new(),
                ts("2027-06-01T00:00:00Z")
            )
            .err(),
            Some(SealRefusal::KeysUnavailable)
        );
        let mut revoked = keys();
        revoked.revoke(&KeyId::parse("ingress/k1").unwrap());
        assert_eq!(
            seal(
                &conn(1001),
                &proposal(&[]),
                &revoked,
                &MemoryKeyRegistry::new(),
                now()
            )
            .err(),
            Some(SealRefusal::KeysUnavailable)
        );
    }
}
